create or replace function public.submit_quote_payment(raw_token text,p_tx_hash text default null) returns boolean language plpgsql security definer set search_path='' as $$ declare qid uuid; begin select q.id into qid from public.retreat_quotes q where q.payment_token_hash=encode(extensions.digest(raw_token,'sha256'),'hex') and q.status in ('sent','accepted') and q.expiry_date>=current_date; if qid is null then raise exception 'Payment quote has expired or is unavailable'; end if; update public.retreat_quotes set payment_status='payment_submitted',payment_submitted_at=coalesce(payment_submitted_at,now()),payment_tx_hash=coalesce(nullif(trim(p_tx_hash),''),payment_tx_hash) where id=qid; return true; end; $$;
grant execute on function public.submit_quote_payment(text,text) to anon,authenticated;
create or replace function public.verify_quote_payment(p_quote_id uuid,p_tx_hash text default null) returns boolean language plpgsql security definer set search_path='' as $$ begin if not (select retreat_private.is_retreat_admin()) then raise exception 'Not authorized'; end if; update public.retreat_quotes set payment_status='payment_verified',payment_verified_at=coalesce(payment_verified_at,now()),payment_verified_by=auth.uid(),payment_tx_hash=coalesce(nullif(trim(p_tx_hash),''),payment_tx_hash) where id=p_quote_id; return found; end; $$;
revoke all on function public.verify_quote_payment(uuid,text) from public,anon; grant execute on function public.verify_quote_payment(uuid,text) to authenticated;
